mapper.select:
SELECT
#{chatCode} as chatCode,
u.userId,
u.nickName,
(
SELECT content
FROM chatmessage_tbl
WHERE chatCode = #{chatCode}
ORDER BY createAt DESC
LIMIT 1
) AS lastMessage,
(
SELECT COUNT(*)
FROM chatmessage_tbl
WHERE chatCode = #{chatCode}
AND userId != #{userId}
AND isRead = 0
) AS unreadCount
FROM user_tbl u
WHERE u.userId = (
SELECT userId
FROM chatparticipant_tbl
WHERE chatCode = #{chatCode}
AND userId != #{userId}
);
